'use strict';
window.Handover467={
 async page(owner){const t=owner.t,L=owner.L.bind(owner),q=new URLSearchParams(location.search),d=await API.request(owner.base+'/tasks?handover=1'),h=d.handover,category=q.get('category')||'',search=(q.get('search')||'').trim(),rows=h.groups.map(g=>({...g,issues:g.issues.filter(i=>!category||i.category===category)})).filter(g=>g.issues.length&&(!search||[g.document_no,g.customer_name,g.lot_no,...g.issues.map(i=>i.document_no)].join(' ').toLowerCase().includes(search.toLowerCase()))),paging=owner.paging(rows.length,q);
  const responsible=i=>{const kind=i.reason_kind||i.kind;if(['SALES_REVIEW','SALES_CLOSE_REVIEW'].includes(kind))return t('销售经理','Sales Manager');if(['COMMERCE_REVIEW','COMMERCE_CLOSE_REVIEW'].includes(kind))return t('商务部经理','Commercial Manager');if(i.category==='weight')return t('检斤办理岗位','Weighing Role');if(i.category==='location')return t('货位维护岗位','Location Role');if(i.category==='document')return t('单证办理岗位','Document Role');if(/LOGISTICS/.test(kind))return t('物流经理','Logistics Manager');if(/FORMAL|PRODUCTION/.test(kind))return t('生产部经理','Production Manager');if(/LOT_REVIEW|LOAD_REVIEW|CO_SITE|CO_LOAD_REVIEW/.test(kind))return t('现场主管','Site Supervisor');return t('当前获授权办理岗位','Authorized Action Role');};
  const reason=i=>i.category==='weight'?t('实际重量未确认，不能将预计重量当作已知净重。','Actual weight is unconfirmed; expected weight is not confirmed net weight.'):i.category==='location'?t('实存货物尚未登记货位。','Physical stock has no recorded location.'):i.category==='document'?t('正式出库后尚未生成装箱单。','A packing list has not been generated after formal outbound.'):t(...owner.kind(i.reason_kind||i.kind));
  const tabs='<nav class="c461-tabs">'+[['pending','待我处理','Pending'],['handover','交接异常清单','Shift Handover'],['initiated','我发起的','Initiated by Me'],['completed','已办理','Handled by Me']].map(([v,z,e])=>'<a href="/overview?management=todos&tab='+v+'"'+(v==='handover'?' aria-current="page"':'')+'>'+L(z,e)+'</a>').join('')+'</nav>',filter='<form id="handover467-filter" class="c461-filter filters"><input type="hidden" name="management" value="todos"><input type="hidden" name="tab" value="handover"><label>'+L('异常类别','Issue Type')+'<select name="category"><option value="">'+t('全部','All')+'</option>'+Object.entries(h.categories).map(([k,v])=>'<option value="'+k+'"'+(k===category?' selected':'')+'>'+esc(t(...v))+'</option>').join('')+'</select></label><label>'+L('单据／客户／批次','Document / Customer / Batch')+'<input name="search" maxlength="160" value="'+esc(search)+'"></label><div class="c461-filter-actions"><button class="button primary">'+L('查询','Search')+'</button><a class="button secondary" href="/overview?management=todos&tab=handover">'+L('重置','Reset')+'</a></div></form>';
  const cards=rows.slice(paging.start,paging.start+20).map(g=>'<article class="handover467-group"><header><div><h3 data-no-i18n>'+esc(g.document_no||'—')+'</h3><p data-no-i18n>'+esc(g.customer_name&&g.customer_name!=='客户未关联'?g.customer_name:t('客户未关联','No Customer Linked'))+'</p></div><span>'+t('最长已知等待 ','Longest Known Wait ')+(g.wait_hours==null?t('开始时间未记录','Start Not Recorded'):Math.floor(g.wait_hours)+t(' 小时',' hours'))+'</span></header><ul>'+g.issues.map(i=>'<li><div><strong>'+esc(t(...h.categories[i.category]))+'</strong><p>'+esc(reason(i))+(i.quantity?' · '+i.quantity+t(owner.co?' 袋':' 捆',owner.co?' bags':' bundles'):'')+'</p><small>'+t('责任岗位：','Role: ')+esc(responsible(i))+'</small></div>'+(i.sources?.length?'<details class="handover467-sources"><summary>'+L('查看原记录','Source Records')+' ('+i.sources.length+')</summary>'+i.sources.map(s=>'<a data-no-i18n href="'+esc(s.href)+'">'+esc(s.document_no)+'</a>').join('')+'</details>':'<a href="'+esc(i.href)+'">'+L('进入原单据 →','Open Original →')+'</a>')+'</li>').join('')+'</ul></article>').join('')||'<p>'+L('当前授权范围无此类异常。','No matching issues in your authorized scope.')+'</p>';
  owner.page('交接班异常清单','Shift Handover Issues',owner.co?'CO-03':'CU-03',tabs+filter+owner.card('本班待交接','Issues to Hand Over','<p class="c461-muted-text">'+L('同一批次合并展示；等待时长未知时不估算。','Grouped by batch; unknown waiting times are not estimated.')+'</p><p>'+L('数据时点','As of')+' <span data-no-i18n>'+esc(owner.time(h.as_of))+'</span> · '+rows.length+L(' 组',' groups')+'</p>'+cards+owner.pager(rows.length,paging.page)));
  document.getElementById('handover467-filter').onsubmit=e=>{e.preventDefault();Router.go('/overview?'+new URLSearchParams(new FormData(e.target)));};owner.bindPager(paging.page);
 }
};
